#include <cuda_runtime.h>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <stdexcept>
namespace infini::ops::dsv4_index_scores_detail {
__device__ float decode(unsigned char b){unsigned e=(b>>3)&15,m=b&7;float v=e?ldexpf(1.f+float(m)/8,int(e)-7):ldexpf(float(m),-9);return b&128?-v:v;}
__global__ void validate_lengths(const int32_t*v,size_t t,size_t keys,int*maximum,int*status){for(size_t i=size_t(blockIdx.x)*blockDim.x+threadIdx.x;i<t;i+=size_t(gridDim.x)*blockDim.x){if(v[i]<0||size_t(v[i])>keys)atomicOr(status,1);else atomicMax(maximum,int(v[i]));}}
__global__ void validate_features(const unsigned char*q,const float*w,const unsigned char*k,const float*s,const int32_t*v,size_t t,size_t h,const int*maximum,int*status){if(*status)return;for(size_t i=size_t(blockIdx.x)*blockDim.x+threadIdx.x;i<t*h*128;i+=size_t(gridDim.x)*blockDim.x)if(v[i/(h*128)]>0){if((q[i]&127)==127)atomicOr(status,2);if(i%128==0&&!isfinite(w[i/128]))atomicOr(status,2);}for(size_t i=size_t(blockIdx.x)*blockDim.x+threadIdx.x;i<size_t(*maximum)*128;i+=size_t(gridDim.x)*blockDim.x){if((k[i]&127)==127)atomicOr(status,2);if(i%128==0&&(!isfinite(s[i/128])||s[i/128]<=0))atomicOr(status,2);}}
__global__ void scores(float*out,const unsigned char*q,const float*w,const unsigned char*k,const float*s,const int32_t*v,size_t tokens,size_t heads,size_t keys,const int*status){if(*status)return;__shared__ float key[128],partial[128],contribution[128];size_t lane=threadIdx.x%16,group=threadIdx.x/16;
 for(size_t pair=blockIdx.x;pair<tokens*keys;pair+=gridDim.x){size_t t=pair/keys,ki=pair%keys;if(ki>=size_t(v[t])){if(threadIdx.x==0)out[pair]=-INFINITY;continue;}key[threadIdx.x]=decode(k[ki*128+threadIdx.x]);contribution[threadIdx.x]=0;__syncthreads();
  for(size_t start=0;start<heads;start+=8){size_t h=start+group;float dot=0;if(h<heads)for(size_t d=lane;d<128;d+=16)dot=__fadd_rn(dot,__fmul_rn(decode(q[(t*heads+h)*128+d]),key[d]));partial[threadIdx.x]=dot;__syncthreads();for(unsigned span=8;span;span>>=1){if(lane<span)partial[threadIdx.x]=__fadd_rn(partial[threadIdx.x],partial[threadIdx.x+span]);__syncthreads();}if(lane==0&&h<heads)contribution[h]=__fmul_rn(fmaxf(__fmul_rn(partial[threadIdx.x],s[ki]),0.f),w[t*heads+h]);__syncthreads();}
  for(unsigned span=64;span;span>>=1){if(threadIdx.x<span)contribution[threadIdx.x]=__fadd_rn(contribution[threadIdx.x],contribution[threadIdx.x+span]);__syncthreads();}if(threadIdx.x==0)out[pair]=contribution[0];__syncthreads();
 }
}
void Launch(void*out,const void*q,const void*w,const void*k,const void*s,const void*v,void*status,void*workspace,size_t tokens,size_t heads,size_t keys,cudaStream_t stream){auto check=[](cudaError_t x){if(x!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(x));};auto flag=static_cast<int*>(status),maximum=static_cast<int*>(workspace);check(cudaMemsetAsync(flag,0,4,stream));check(cudaMemsetAsync(maximum,0,4,stream));validate_lengths<<<unsigned(std::min<size_t>((tokens+255)/256,256)),256,0,stream>>>(static_cast<const int32_t*>(v),tokens,keys,maximum,flag);check(cudaGetLastError());validate_features<<<256,256,0,stream>>>(static_cast<const unsigned char*>(q),static_cast<const float*>(w),static_cast<const unsigned char*>(k),static_cast<const float*>(s),static_cast<const int32_t*>(v),tokens,heads,maximum,flag);check(cudaGetLastError());scores<<<unsigned(std::min<size_t>(tokens*keys,65535)),128,0,stream>>>(static_cast<float*>(out),static_cast<const unsigned char*>(q),static_cast<const float*>(w),static_cast<const unsigned char*>(k),static_cast<const float*>(s),static_cast<const int32_t*>(v),tokens,heads,keys,flag);check(cudaGetLastError());}
}
